globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-23 15:41:19 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"2026年11月21日をもって世界はシンギュラリティに突入した｜たてはま","url":"https://note.com/cgbeginner/n/n5856d402f125","source":"Hatena","published_at":"2026-11-22 22:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIと数学者が共同で「リーマン予想」を証明、数学界に衝撃","summary":"2026年11月21日、AnthropicのAI「Claude」と数学者レヴェント・アルポーゲ氏の共同作業により、167年間未解決だった数学の超難問「リーマン予想」の証明が公開された。証明は「Lean」という証明支援系言語で記述され、コミュニティによる検証で論理的な正しさが確認された。\n\n特筆すべきは、この証明が約1,700万行のコードとして公開され、人間が読める論文形式ではない点だ。専門家ですら全体を理解できていない現状は、AIが人間を超越した推論を行う「シンギュラリティ」の到来を予感させる。今後は、この膨大なコードを人間が理解可能な形に整理・検証する新たなフェーズが始まる。","importance":10},{"title":"AWS WAF Security Analytics ダッシュボードを検証した。WAF ログのクエリ調査は卒業できるか","url":"https://zenn.dev/mortrainer/articles/d2e4ddedda783e","source":"Zenn","published_at":"2026-11-23 11:05","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWS WAF Security Analyticsダッシュボード検証、ログクエリ調査の卒業は可能か","summary":"AWS WAFの新機能「Security Analyticsダッシュボード」を検証。Athena等でのログクエリ調査を代替できるか、複数Web ACLの横断表示やブロック操作の利便性を確認した。\n\nダッシュボードの集計精度はログと一致し、直感的なフィルタリングや深掘り調査が可能。また、IPセットの自動作成によるブロック操作も実装されており、従来の運用負荷を大幅に軽減できる可能性がある。ただし、一部の攻撃パターンが検知から漏れるケースもあり、運用の注意点も示唆されている。","importance":8},{"title":"通信が切れて作られなかった振り返りを、会話ごとの ID で送り直す――Flutter と Cloud Functions の4つの穴","url":"https://zenn.dev/wa_rp_studio/articles/flutter-firebase-feedback-retry","source":"Zenn","published_at":"2026-11-23 12:00","genre":"web","genre_label":"Web開発・言語","headline":"Flutterアプリで通信失敗時の「振り返り」を確実に送るための実装と罠","summary":"英会話アプリにおいて、通信断絶時にAIによる振り返り生成が失敗する問題を解決するための実装手法。会話ごとのIDを用いた冪等な処理と、端末への依頼保存による再送ロジックを解説する。\n\n実装過程で判明した「通信失敗を回数制限に含めてしまう」「Androidのライフサイクルイベントによる意図しない再送」「ログインユーザーの切り替わり」といった4つの落とし穴と、それらに対するトランザクション管理や間隔制御などの対策が詳細にまとめられている。","importance":7},{"title":"世界初の直径200mm単結晶ダイヤモンドウェハーは何を変えるのか、AIチップの99％をダイヤモンドにする構想とは？","url":"https://gigazine.net/news/20261123-diamond-foundrysingle-crystal-diamond/","source":"Hatena","published_at":"2026-11-23 09:10","genre":"other","genre_label":"総合・その他IT","headline":"世界初200mm単結晶ダイヤモンドウェハーが切り拓くAIチップ冷却の未来","summary":"Diamond Foundryが世界初となる直径200mmの単結晶ダイヤモンドウェハーの製造に成功。ダイヤモンドの極めて高い熱伝導率を活かし、AIチップの局所的な発熱（ホットスポット）問題を解消する構想が注目されている。\n\n既存のシリコン半導体技術とダイヤモンドを接合することで、チップの冷却性能を飛躍的に向上させることが可能。電力密度を維持しつつ温度を大幅に下げる実験結果も出ており、次世代の高性能AIチップ製造における重要なブレイクスルーとなる可能性がある。","importance":9},{"title":"AndroidスマホがWindows PCのサブ画面に？マイクロソフトが新機能 - すまほん!!","url":"https://smhn.info/202611-microsoft-link-to-windows-extend-display-android-second-screen","source":"Hatena","published_at":"2026-11-22 21:29","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AndroidスマホがWindowsのサブディスプレイになる新機能","summary":"MicrosoftがAndroidアプリ「Windows にリンク」において、スマホやタブレットをWindows PCの拡張ディスプレイとして利用する「Extend display」機能を開発中であることが判明した。アプリ内のコードやアイコンから、PC画面を無線でスマホへ転送する仕組みが示唆されている。\n\n実現すれば、既存のミラーリング機能を超えて、古いAndroid端末を有効活用できるサブモニターとして利用可能になる。Samsungなどの特定メーカーに依存しない汎用的な機能としての実装が期待されており、PCとモバイルの連携を強化する重要なアップデートとなる。","importance":7},{"title":"席替えのたびに半日消えていた作業を1時間にした、レイアウト変更の5つの工夫","url":"https://zenn.dev/solo_joshis/articles/2026-10-19-5tips-callcenter-50","source":"Zenn","published_at":"2026-11-23 09:00","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"席替え作業を半日から1時間に短縮、情シスが実践した5つの効率化工夫","summary":"コールセンターの情シス担当者が、頻繁な席替え作業を効率化するために実践した5つの工夫。属人化していた座席管理を台帳化し、依頼フローを改善することで作業時間を大幅に短縮した。\n\n席IDの固定化、移動者一覧による依頼の標準化、席に依存しない設定への移行、ケーブルへのラベル貼付、本人によるセルフチェックの導入が鍵。業種を問わず応用可能な、管理コストを削減するための実践的な組織運営の知見である。","importance":5},{"title":"Hermesで会話とUIをつなぐ、AI対話Pluginのアーキテクチャ","url":"https://zenn.dev/toshibowie/articles/01d4393e980018","source":"Zenn","published_at":"2026-11-23 11:41","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"HermesでAI対話とUIを連携させるプラグインアーキテクチャの設計","summary":"AIモデルの対話とReact UIを連携させ、フォーム入力や実行をスムーズに行うためのプラグインアーキテクチャ。モデルのtool呼び出し、手順書（SKILL.md）、UI変換（directive）を組み合わせた設計を解説する。\n\nモデルとUI間で値を共有する際の課題に対し、SQLiteを導入してセッションごとの下書きを管理する手法を採用。これにより、会話のターンを跨いだ値の保持や、二重送信の防止、モデルとUIの双方向なデータ連携を実現した。","importance":8},{"title":"箱入り娘ソルバーを約9,400倍高速化してもらった","url":"https://zenn.dev/kaorun343/articles/klotski-solver-optimization","source":"Zenn","published_at":"2026-11-23 11:32","genre":"other","genre_label":"総合・その他IT","headline":"Rust製パズルソルバーを約9,400倍高速化した最適化手法の全記録","summary":"箱入り娘パズルのソルバーを、Rustを用いて劇的に高速化した事例。幅優先探索のアルゴリズム改善、重複判定の効率化、ビットボードによる盤面表現の導入など、段階的な最適化プロセスを解説する。\n\n特に、同じ形のブロックを区別しない正規化や、盤面をu64に収めるビットボード化が劇的な効果を発揮し、局面数を大幅に削減。メモリ使用量と計算時間を劇的に改善した技術的アプローチは、他の探索問題にも応用可能な知見である。","importance":7},{"title":"ホルムズ海峡におけるイランの攻撃、紛争開始以来の最高水準に　海事データ分析","url":"https://www.cnn.co.jp/world/35255291.html","source":"Hatena","published_at":"2026-11-23 13:58","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ホルムズ海峡で船舶攻撃が急増、イランの関与と地政学的リスクが深刻化","summary":"ホルムズ海峡および周辺海域における船舶への攻撃報告件数が、軍事衝突開始以来最多水準に達している。海事データの分析により、イラン政府が影響力を誇示するために攻撃をエスカレートさせている可能性が指摘されている。\n\n原油価格の下落に伴い、イランが米国から譲歩を引き出すための手段として攻撃を強めているとの見方がある。多くの船舶が追跡装置をオフにするなど、海事リスクは極めて高く、世界経済への悪影響が懸念されている。","importance":7},{"title":"AIに実装を任せても、理解と判断は手放さない：基準・証拠・説明をGoのAPIで試した記録","url":"https://zenn.dev/kinuuu/articles/ai-coding-criteria-evidence-explanation","source":"Zenn","published_at":"2026-11-22 23:21","genre":"web","genre_label":"Web開発・言語","headline":"AI実装を任せても理解を手放さないための「基準・証拠・説明」のプロセス","summary":"AIに実装を任せる際、コードを理解し、マージの根拠を説明できる状態を保つための開発プロセスを提案した記事です。実装前に「基準」を決め、テスト結果を「証拠」とし、変更内容を自分の言葉で「説明」するという3つのステップをGoのAPI開発で実践しています。\n\nAIによる実装は高速ですが、理解負債（comprehension debt）を抱えるリスクがあります。レビュアーに聞かれる前に自分自身で問いを立て、判断の材料を揃えることで、AIを使いこなしつつも開発者としての責任を果たすための具体的な手法が示されています。","importance":8},{"title":"iPhone DuoとGalaxy Z Fold8で「サイゼリヤの注文画面」を開いて分かった意外な事実　折りたたみならではの活用法も","url":"https://www.itmedia.co.jp/mobile/articles/2611/23/news006.html","source":"Hatena","published_at":"2026-11-23 12:13","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"折りたたみスマホでサイゼリヤ注文画面が使えない？画面比率の壁と解決策","summary":"折りたたみスマートフォンの大画面でサイゼリヤのモバイルオーダーを利用する際、画面比率が原因で「縦画面」と認識されず注文できない問題が発生している。iPhone DuoやGalaxy Z Fold8などの最新機種での検証結果を解説。\n\n解決策として、端末の持ち方を変える、画面分割機能でブラウザの表示領域を調整するなどの工夫が有効である。大画面を活かしたマルチウィンドウ活用は、注文画面とメニューを同時に見比べられるという、折りたたみ端末ならではの利点も示している。","importance":5},{"title":"なぜ駅の改札機で混乱？　Suica、クレカ、QRコードの集約で「立ち止まらない快適さ」を奪う理由","url":"https://www.itmedia.co.jp/mobile/articles/2611/23/news005.html","source":"Hatena","published_at":"2026-11-23 11:34","genre":"other","genre_label":"総合・その他IT","headline":"改札機のタッチ決済集約で生じる混乱、UI/UXの課題と技術的制約","summary":"鉄道改札へのタッチ決済導入により、ICカード、クレカ、QRコードが混在し、利用者がタッチ位置に迷う混乱が起きている。歩行を止めないという日本の改札体験が、情報過多により損なわれている現状を分析。\n\n技術的には、複数の決済手段を瞬時に判別する仕組みの難しさが、センサーの物理的な分散を招いている。利便性の向上を目指したシステム統合が、かえって現場の混乱や追突リスクを生んでいるという、技術実装と現場体験の乖離が浮き彫りとなっている。","importance":6},{"title":"この時代に、なぜ技術カンファレンス・勉強会に行くのか｜Subaru Nakamura(varu3)","url":"https://note.com/varu3/n/n4476366008f8","source":"Hatena","published_at":"2026-11-22 23:37","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"オンライン全盛時代に技術カンファレンスへ現地参加する価値とは","summary":"技術情報の入手がオンラインで完結する時代において、あえてカンファレンスや勉強会に現地参加する意義を考察した記事です。著者は、セッション内容の把握だけならオンラインが合理的であると認めつつ、現地参加の価値を「不確実性」と「対面での対話」に見出しています。\n\n登壇者とのスライド外の会話や、懇親会での偶発的な出会いなど、予定調和ではない体験こそが現地参加の醍醐味であると説いています。CNDW2026の運営として、会話が生まれる場をデザインした経験を交え、コミュニティにおける対面の価値を再定義しています。","importance":5},{"title":"OpenAIのチーフサイエンティスト、AI開発に業界共通の「上限」を提案　指標は「パープレキシティ」","url":"https://www.itmedia.co.jp/news/article/2611/23/2000003394/","source":"Hatena","published_at":"2026-11-23 08:16","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"OpenAIチーフサイエンティストがAI開発の共通上限「パープレキシティ」を提案","summary":"OpenAIのヤクブ・パチョキ氏は、AIの予測精度を示す指標「パープレキシティ」を業界共通の物差しとし、開発の上限を設けるよう提案する論考を公開しました。同氏は、事前学習の急加速により2027年にも根本的な進歩が起きる可能性がある一方、監視技術が追いつかないリスクを懸念しています。\n\nパチョキ氏は、GPT-3.5から最新モデルまでの推移をグラフで示し、特定の数値で変革的な能力が創発することを指摘しました。これに対し、サム・アルトマンCEOも賛同しており、業界全体で安全対策を確立するための緊急の提言として注目されています。","importance":9},{"title":"pgvector の ef_search が asyncpg のプールで消え、recall@10 が 97.95%→86.05% に落ちた","url":"https://zenn.dev/tama_program/articles/pgvector-asyncpg-ef-search-reset","source":"Zenn","published_at":"2026-11-23 07:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"asyncpgのプール利用でpgvectorのef_search設定が消える問題と性能劣化","summary":"PostgreSQLの拡張機能pgvectorにおいて、asyncpgのコネクションプールを使用する際に、接続のRESET ALLによって設定したパラメータが消失し、検索精度（recall@10）が大幅に低下する問題の検証記事です。\n\n検証の結果、接続の使い回しによって設定が失われ、recall@10が97.95%から86.05%まで低下することが判明しました。開発時のテストでは暖機直後の状態を見てしまい問題に気づきにくいという罠があり、本番環境での適切なパラメータ設定と監視の重要性を説いています。","importance":8},{"title":"ここ1か月くらい、PCに勝手に Adobe Express Photos が勝手にインストールされたっていう問い合わせが多発してるんですが、さすがにこれはAdobeさんやりすぎじゃないでしょうか・・・？ しかも、Windows+Shift+Sを勝手に上書きして、機能劣化版のスクショツールに置き換わるんですよ…→「これマジでクソ過ぎてAdobe系製品全部消したい」","url":"https://posfie.com/@petaritape/p/tgzVdbL","source":"Hatena","published_at":"2026-11-23 07:04","genre":"other","genre_label":"総合・その他IT","headline":"Adobe Express Photosの勝手なインストールとスクショ機能上書きへの批判","summary":"Adobe Acrobat Readerのアップデートに伴い、「Adobe Express Photos」がユーザーの同意なくインストールされ、Windowsの標準スクリーンショット機能（Win+Shift+S）が上書きされる事象が多発しているという報告です。\n\nユーザーからは、使い勝手の悪化やダークパターン的なインストール手法に対する強い批判が上がっています。セキュリティやOSの操作性を損なう挙動に対し、Adobe製品のアンインストールを検討するユーザーも現れており、ソフトウェアの更新ポリシーに対する不信感が広がっています。","importance":6},{"title":"Webメール開発を大幅に変えたJMAPというゲームチェンジャー","url":"https://speakerdeck.com/tascript/jmap-is-game-changer","source":"Hatena","published_at":"2026-11-23 00:40","genre":"web","genre_label":"Web開発・言語","headline":"Webメール開発のゲームチェンジャー「JMAP」の基礎とメリット","summary":"JSConfJP 2026の登壇資料を基に、Webメール開発を効率化するプロトコル「JMAP（JSON Meta Application Protocol）」について解説した記事です。従来のIMAP+SMTPの複雑な構成に対し、JMAPはHTTP/JSONベースでメール操作を可能にします。\n\nJMAPはステートレスな通信や効率的な同期を実現し、ブラウザからの直接的なメール操作を容易にします。RFCで標準化されたこのプロトコルが、いかにWebメール開発の課題を解決し、リアルタイム同期やオフライン対応を可能にするかという実践的な知見がまとめられています。","importance":7},{"title":"PixelのLinux TerminalでHyprlandを動かす","url":"https://zenn.dev/jhoshina/articles/cd9b4fe6ba9d62","source":"Zenn","published_at":"2026-11-22 22:07","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"PixelのLinux TerminalでHyprlandをネイティブ動作させる","summary":"PixelのLinux Terminal環境において、標準のWestonを置き換える形でWaylandコンポジタ「Hyprland」をネイティブ動作させることに成功した事例。systemdのユーザーサービスをオーバーライドし、GPUアクセラレーション環境変数を適切に設定することで実現している。\n\n描画性能には制限があるものの、モバイル端末上のLinux環境で高度なウィンドウマネージャを動かすための技術的知見として価値がある。同様の手順で他のコンポジタも起動可能であり、モバイル端末のLinux環境をカスタマイズしたいユーザーにとって有用な情報である。","importance":5},{"title":"作れるエンジニアから、価値を届けるエンジニアへ","url":"https://zenn.dev/kubell/articles/3c3490a3592bb1","source":"Zenn","published_at":"2026-11-21 00:50","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"エンジニアが「作る」から「価値を届ける」へ役割を広げる方法","summary":"AIの普及により実装コストが低下した今、エンジニアが「何を作るか」という意思決定にどう関与すべきかを考察。ターゲット選定、ペインの特定、体験価値の設計という3つの観点から、価値あるプロダクトを生み出すためのアプローチを解説しています。\n\n単に仕様通りに作るだけでなく、ユーザーの真のニーズを理解し、サービス全体で価値を届ける姿勢が重要だと強調。エンジニアがプロダクトマネジメントの領域へ役割を広げるための実践的な指針を示しています。","importance":7},{"title":"ゲホゲホ咳をしながらAVを観てたら外部サイトに飛んで「めっちゃ咳き込んでるんだけどこの人、子供だよね？シー🤫」みたいな話し声が携帯から聞こえてきてガチで怖い","url":"https://togetter.com/li/2773923","source":"Hatena","published_at":"2026-11-23 14:44","genre":"other","genre_label":"総合・その他IT","headline":"AV視聴中に外部サイトから音声が聞こえる怪奇現象、セキュリティリスクの可能性","summary":"AV視聴中に外部サイトへ遷移し、自身の咳に反応するような話し声が聞こえたという体験談。Webブラウザの権限設定や、悪意ある広告・ライブ配信サイトによるインカメラ・マイクの不正利用リスクが指摘されている。\n\n専門家やユーザーからは、聴覚性パレイドリア（無意味な音を意味のある言葉と誤認する現象）の可能性も示唆されているが、インカメラの物理的な遮断やアプリの権限確認など、プライバシー保護の重要性が改めて強調されている。","importance":4},{"title":"Claude Code の mods を入れる前に調べたこと（備忘録）","url":"https://zenn.dev/shogaku/articles/claude-code-mods-memo","source":"Zenn","published_at":"2026-11-23 10:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeの「mods」機能導入前に知るべきセキュリティと仕様の注意点","summary":"Claude Codeの拡張機能「mods」の仕様とセキュリティリスクに関する備忘録。TypeScriptでClaude Codeの挙動をカスタマイズできる強力な機能だが、サンドボックス外で動作するため注意が必要である。\n\nmodは利用者の権限でファイル操作やネットワーク接続が可能であり、信頼できないソースからの導入は危険である。特に個人プランでは組み込みの保護機能が一部制限されるため、導入前に公式ドキュメントやセキュリティリスクを十分に理解することが推奨される。","importance":7},{"title":"[アップデート]AWSアカウント作成がとんでもなく別物になったので動作の違いを見てみた[新しいAWSエクスペリエンス] | DevelopersIO","url":"https://dev.classmethod.jp/articles/new-aws-signup/","source":"Hatena","published_at":"2026-11-23 02:32","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AWSアカウント作成の仕組みが刷新、新エクスペリエンスの注意点","summary":"AWSアカウント作成プロセスが大幅に変更され、デフォルトで「新しいAWSエクスペリエンス」が適用されるようになったことに関する解説記事です。従来のAWSアカウント作成とは管理単位やリージョン選択の制約が大きく異なり、注意が必要です。\n\n新しい仕組みでは「プロジェクト」や「チーム」といった概念が導入され、AWS Builder IDが自動作成されます。従来のフル機能を利用したい場合は「advanced features」を選択する必要があり、組織利用や詳細な設定が必要なケースとの使い分けが重要であることを強調しています。","importance":8},{"title":"リリースしたで終わらない。 観測できるフロントエンド開発","url":"https://speakerdeck.com/yamakenji24/20261122-jsconf2026-lt-kenji-yamashita","source":"Hatena","published_at":"2026-11-22 20:10","genre":"web","genre_label":"Web開発・言語","headline":"フロントエンド開発におけるリリース後の価値検証サイクル","summary":"リリースして終わりではなく、UI改善の効果を定量的に検証するための開発サイクル構築について解説。リファインメント段階での指標設計、開発タスクとしてのイベント仕込み、定期的な観測会を組み込むことで、価値検証を安定化させている。\n\nエンジニアがPdMと協力し、計測に必要なデータを設計・実装することで、リリースした機能が本当にユーザーの課題を解決したかを判断可能にする。開発プロセスに「観測」を組み込むことで、改善の質を高めるための実践的なアプローチである。","importance":7},{"title":"証明が得られたあとに−−証明を理解するという仕事｜加藤文元","url":"https://note.com/katobungen/n/n2326bd68a80e","source":"Hatena","published_at":"2026-11-22 15:23","genre":"other","genre_label":"総合・その他IT","headline":"AI時代の数学証明：理解を広げるための「読み解く仕事」","summary":"AIがリーマン予想を証明したことを受け、膨大な形式的証明を人間が理解可能な形へ再構築する重要性を論じる。フェルマーの最終定理や特異点解消定理の先例を引き合いに、証明の全体像を把握し、論理の筋道を噛み砕くプロセスが数学の発展に不可欠であると説く。\n\nAIが生成した証明を、人間が教育や研究に活用できる形に変換する作業は、今後数学者にとって重要な役割となる。証明の正しさを確認するだけでなく、その背後にある「考え方」を共有する文化の重要性を再認識させる論考である。","importance":7},{"title":"Kindleも使えて漫画も見開きで読める！ パカッと開く電子書籍端末「Inkleaf」 | ギズモード・ジャパン","url":"https://www.gizmodo.jp/article/2611-inkleaf-dual-screen-ereader/","source":"Hatena","published_at":"2026-11-22 09:48","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"見開き表示対応の10.3インチ電子ペーパー端末「Inkleaf」","summary":"10.3インチの電子ペーパーを2枚搭載し、紙の本のように見開きで読書ができる電子書籍端末「Inkleaf」を紹介。Kindleアプリにも対応しており、漫画や小説を見開きで快適に読める点が最大の特徴です。\n\nPDFへの手書きメモ機能や4,096段階の筆圧検知ペンも付属しており、読書だけでなくノート代わりとしての活用も可能。Kickstarterでの展開が予定されており、電子書籍リーダーの新たな選択肢として注目されます。","importance":5},{"title":"Claude Code を安全に「自走」させるなら、もう Docker Sandboxes 一択でよくない？と思った話。｜YamaC / ﾔﾏｼｰ","url":"https://note.com/yamac_/n/n198bdc344c64","source":"Hatena","published_at":"2026-11-22 19:08","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI Coding Agentの安全な自走にはDocker Sandboxesが最適","summary":"Claude CodeなどのAIコーディングエージェントを安全に運用するため、Docker Sandboxes（sbx）を活用する手法を提案。MicroVMによるカーネルレベルの隔離と、デフォルト拒否の通信制限により、ホスト環境へのリスクを最小限に抑えつつ自律的な開発が可能になる。\n\n従来のコンテナよりも強力なセキュリティモデルを備えており、Enterprise環境での利用にも適している。AIに環境設定やコード実行を任せる際、セキュリティと利便性を両立させるための現実的な解として、Docker Sandboxesの導入が推奨される。","importance":8},{"title":"CloudWatch Agentがjournaldを直接読めるようになったので、AL2023で試した","url":"https://zenn.dev/smori/articles/cloudwatch-logs-journald-collection","source":"Zenn","published_at":"2026-11-22 21:07","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CloudWatch Agentがjournaldログを直接収集可能に","summary":"CloudWatch Agentのアップデートにより、rsyslogや中間ファイルを介さず、journaldのログを直接CloudWatch Logsへ送信可能となった。Amazon Linux 2023のようなjournald主体の環境において、ログ収集の構成が大幅に簡素化される。\n\nエージェントは内部でjournalctlコマンドを利用しており、ユニット名や優先度によるフィルタリングも可能。監査ログやカーネルログを含むシステム全体のログ管理が効率化され、運用負荷の低減とログの構造化維持が期待できる。","importance":8},{"title":"[Java]ゼロからフルスクラッチでSmith標準形(単因子標準形)を計算させるプログラムを作ってみた","url":"https://zenn.dev/calborg/articles/3b2e3d741ed9e1","source":"Zenn","published_at":"2026-11-22 17:15","genre":"other","genre_label":"総合・その他IT","headline":"JavaによるSmith標準形計算プログラムのフルスクラッチ実装","summary":"多項式を成分に持つ行列のSmith標準形（単因子標準形）を求めるプログラムを、外部ライブラリを使わずJavaでフルスクラッチ実装した技術解説。数学的な理論をコードに落とし込む過程と、多項式の割り算アルゴリズムの設計について詳述している。\n\nSmith標準形はJordan標準形などを導くための重要な数学的ツールであり、その計算手順を自作することで理論への理解が深まる。数学とプログラミングの融合に関心があるエンジニアにとって、アルゴリズムの実装力を試す興味深いテーマである。","importance":4},{"title":"useReducerで実現する、堅牢で拡張可能なスプシ風コンポーネント設計","url":"https://speakerdeck.com/arfes0e2b3c/jsconf2026-yata?slide=12","source":"Hatena","published_at":"2026-11-22 23:39","genre":"web","genre_label":"Web開発・言語","headline":"useReducerを活用した堅牢で拡張可能なスプレッドシート風コンポーネント設計","summary":"業務アプリケーションにおいて、スプレッドシートに負けないユーザー体験を提供するためのコンポーネント設計について解説した記事です。状態管理にuseReducerを採用することで、複雑な操作を堅牢かつ拡張可能な形で閉じ込める手法を紹介しています。\n\nuseStateによる自由な状態更新ではなく、reducerを通じて決められた操作のみを許可することで、コンポーネントの堅牢性を高めています。業務アプリ特有の複雑な入力画面を、いかに保守しやすく設計するかというフロントエンドエンジニア向けの知見が共有されています。","importance":6},{"title":"SideLoadをしよう！〜SideStoreをiPhone単体で入れる〜(SideInstaller編)","url":"https://zenn.dev/l_port8000/articles/7550549e6e9970","source":"Zenn","published_at":"2026-11-22 12:46","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"PC不要でiPhone単体にSideStoreを導入する手順","summary":"PCを使わず、iPhone単体で非公式アプリストア「SideStore」を導入するための「SideInstaller」利用ガイド。iOS 27以上を対象とし、DNSプロファイルの設定や証明書の検証手順をステップバイステップで解説しています。\n\n注意点として、非公式アプリの導入に伴うリスクや、VPN設定との競合回避策についても触れています。あくまで技術的な導入手順の共有であり、アプリの出どころ確認などセキュリティへの配慮を強く推奨しています。","importance":4},{"title":"Orca Botsが良さそう、何ができるのか","url":"https://zenn.dev/kg_motors_mibot/articles/orca-bot-intro","source":"Zenn","published_at":"2026-11-22 00:14","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントを常設・自動化する「Orca Bots」の活用","summary":"AI IDE「Orca」に導入された「Orca Bots」の機能と可能性を解説。Claude CodeなどのAIエージェントに役割や記憶を持たせ、SlackやGitHubと連携して継続的な業務を任せる仕組みです。\n\n単なるAI呼び出しではなく、イベント駆動での自動実行や人間への作業引き継ぎがシームレスに行える点が特徴。開発者が日常業務の中でAIエージェントを「チームの一員」として活用するための実践的なアプローチを提案しています。","importance":9},{"title":"大阪のホテルに宿泊、食事で外出しようとしたらギャルみたいな女性に「ご飯行きませんか？」と誘われ、怖くて無視してホテルの部屋へ戻ってUberで注文した「都会怖いよ」","url":"https://togetter.com/li/2773878","source":"Hatena","published_at":"2026-11-23 08:49","genre":"other","genre_label":"総合・その他IT","headline":"大阪のホテル周辺で遭遇した勧誘トラブル、都会の夜歩きに潜むリスク","summary":"大阪のホテル周辺で、見知らぬ女性から食事に誘われた体験談。美人局やぼったくりバーへの勧誘リスクを懸念し、無視して部屋に戻ったというエピソードから、都市部における夜間の安全対策が議論されている。\n\nSNS上では、同様の勧誘に対する警戒の重要性や、特定のエリアの危険性が指摘されている。旅行先でのトラブルを避けるための防犯意識や、不審な誘いに対する適切な対応策が共有されており、都会の夜歩きにおける注意喚起となっている。","importance":3},{"title":"自宅Linuxサーバーの棚卸し ― Codexによる点検、依存の確認、秘密情報の後始末","url":"https://zenn.dev/megrou/articles/910c239a838b1a","source":"Zenn","published_at":"2026-11-23 12:13","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"AIエージェント「Codex」を活用した自宅Linuxサーバーの棚卸しと最適化","summary":"長年放置していた自宅Linuxサーバーを、AIエージェント「Codex」を用いて点検・整理した事例。読み取り専用のサンドボックス環境でAIに設定ファイルを分析させ、不要なサービスや依存関係を効率的に特定・削除した。\n\nAIによる指摘と人間による実機確認を組み合わせることで、安全かつ迅速なサーバーのクリーンアップを実現。ストレージの圧迫要因だった動画データの移行や、死活監視スクリプトの整理など、運用終了後の後始末まで含めた実践的なサーバー管理手法が紹介されている。","importance":6},{"title":"JSONL を splitlines() で読むと、見えない1文字で行が切れる","url":"https://zenn.dev/xblacktea/articles/5d7eda4b7afdc8","source":"Zenn","published_at":"2026-11-22 22:44","genre":"web","genre_label":"Web開発・言語","headline":"Pythonのsplitlines()がJSONLを破壊する原因と対策","summary":"Pythonのstr.splitlines()が、改行以外の「見えない制御文字（U+2028など）」も行区切りとして認識してしまうことで、JSONLファイルの読み込みエラーが発生する問題について解説。この挙動により、1行のJSONが途中で分割され、パース失敗を招く。\n\n対策として、JSONLの読み込みにはsplitlines()ではなく「\\n」による分割を使用し、書き込み時にはensure_ascii=False設定下でも問題となる制御文字をエスケープすることが推奨される。AI開発の現場で実際に発生したトラブルを基にした、実用的なコーディングの知見である。","importance":6},{"title":"AIがテストに合わせて実装していない？仕様テストを隠して確かめる","url":"https://zenn.dev/h_aso/articles/isolated-spec-tests-claude-code","source":"Zenn","published_at":"2026-11-23 08:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIの実装ミスを防ぐ「Isolated Specification Tests」という検証手法","summary":"AIに実装を依頼する際、仕様書は渡しても「仕様テスト」を隠すことで、AIがテストに合わせた答え合わせ的な実装を行うのを防ぐ手法「Isolated Specification Tests」の検証記事です。Claude Codeを用いて、テストの隔離が実装の品質に与える影響を実験しています。\n\n実験の結果、隔離を行わないとAIが自らテストを読みに行ってしまうことが判明しました。テストを隠すことで、AIによる自己確認を防ぎ、仕様書に基づいた本質的な実装を促すとともに、仕様書の曖昧さや実装の誤りをより正確に検知できる可能性が示されています。","importance":7},{"title":"Blender向けキャラクター作成アドオン「Eden」が登場！AIで生成したモデルを取り込む「Eden Wrap」も","url":"https://cginterest.com/2026/11/20/eden-blender/","source":"Hatena","published_at":"2026-11-21 09:16","genre":"other","genre_label":"総合・その他IT","headline":"Blender用キャラ作成アドオン「Eden」とAI連携機能","summary":"Blender内でキャラクター作成からリギングまで完結できるアドオン「Eden」を紹介。スライダー操作による体型調整や服のフィッティング、アニメーション用リグの生成など、効率的なワークフローを実現します。\n\n拡張機能「Eden Wrap」を使用することで、AIで生成したモデルを取り込み、Edenのツールセットで編集可能にする点も大きな特徴。3Dキャラクター制作のハードルを下げ、制作時間を大幅に短縮するツールとして期待されています。","importance":5},{"title":"PHP(Laravel向け)のdistrolessイメージを作ろうとしてみる","url":"https://zenn.dev/fagai/articles/58b7dcf826b5ec","source":"Zenn","published_at":"2026-11-22 23:35","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Laravel向けPHP Distrolessイメージ作成の試みと脆弱性対策","summary":"PHP（Laravel）環境において、OSやパッケージマネージャーを含まない最小限のDockerイメージ「Distroless」を作成する試みをまとめた記事です。Distrolessを採用することで、脆弱性を大幅に削減できるメリットを検証しています。\n\nlddコマンドを用いて必要なライブラリを抽出し、Distrolessイメージへ移植する手順を解説しています。結果として脆弱性スキャンで「0」を達成しており、本番環境におけるセキュリティ強化策としてDistrolessの有効性が示されています。Laravel特有の依存関係管理についても言及されています。","importance":7},{"title":"MCP サーバーを OAuth 込みで、SDK を入れずに書いた","url":"https://zenn.dev/umunet/articles/f21b486d234a03","source":"Zenn","published_at":"2026-11-22 13:58","genre":"web","genre_label":"Web開発・言語","headline":"SDKを使わずOAuth対応のMCPサーバーを実装する","summary":"Claudeから利用可能なMCPサーバーを、公式SDKを使わずにNext.jsのRoute Handlerで実装した事例。OAuthによる認証を組み込み、トークン管理を不要にすることで、ユーザー体験とセキュリティを両立させている。\n\nSDKに依存せずプロトコルを直接実装することで、コードの可読性と保守性を高め、認証フローの挙動を完全に制御している。MCPの仕様を深く理解し、ステートレスな設計でCloud Run等の環境に最適化する手法は、高度なWeb開発の参考になる。","importance":7},{"title":"17.6GB の Inkling 2 Mini を 12GB の GPU で動かす。置き方で 21→30、改造で 36 トークン／秒","url":"https://zenn.dev/gucchinworks/articles/inkling-2-mini-12gb","source":"Zenn","published_at":"2026-11-22 22:50","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"12GB GPUで17.6GBのLLMを動かす最適化手法の検証","summary":"12GBのVRAMを搭載したGPUで、17.6GBの量子化モデル「Inkling 2 Mini」を効率的に動作させるための検証記録。llama.cppを用い、モデルの層をGPUとCPUにどのようにオフロードするかで生成速度が21〜36トークン/秒まで大きく変動することが示された。\n\n結論として、ループ層のエキスパートのみをGPUに配置する手法や、エキスパートキャッシュの改造を行うことで、ハードウェアの制約を超えてパフォーマンスを最大化できることが判明した。VRAM容量が不足する環境でのLLM運用において、メモリ配置の最適化が極めて重要であることを示唆している。","importance":7},{"title":"なんでみんなそんなにセルフレジに戸惑うんだ？ UIや導線が統一されてない..","url":"https://anond.hatelabo.jp/20261122011458","source":"Hatena","published_at":"2026-11-22 01:15","genre":"other","genre_label":"総合・その他IT","headline":"セルフレジのUI統一とユーザー体験に関する考察","summary":"セルフレジのUIや導線がバラバラで戸惑うという声に対し、スマホアプリやゲームなど他のシステムも同様にUIは統一されていないと指摘する議論。なぜセルフレジだけが特に嫌悪されるのか、その背景にある心理や操作性の課題を掘り下げています。\n\nユーザー側からは「説明書への導線がない」「業務の押し付け」といった不満が挙げられる一方、ゲーマーは操作を攻略対象と捉えるといった興味深い視点も提示。UIデザインの標準化とユーザー教育の重要性が浮き彫りになっています。","importance":3},{"title":"WolvCTF2026 - writeup","url":"https://zenn.dev/gattoartz/articles/3f302189a1741a","source":"Zenn","published_at":"2026-11-23 11:53","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"WolvCTF2026のWriteup：パストラバーサルやIDORを活用した攻略手法","summary":"WolvCTF 2026における一部問題の攻略解説。AIを使用せず、ソースコード解析やパストラバーサル、IDOR（不適切なアクセス制御）の脆弱性を突くことでフラグを獲得するプロセスが紹介されている。\n\n特に、JavaScriptのeveryメソッドの仕様を悪用した認証回避や、画像メタデータに隠された情報の抽出など、CTF特有のテクニックが網羅されている。ソースコードの静的解析がいかに重要であるかを示す実例となっている。","importance":5},{"title":"spec as code ではなく、code as spec — 仕様書のように書かれたコードを正にする","url":"https://zenn.dev/ruri/articles/code-as-spec","source":"Hatena","published_at":"2026-11-06 23:28","genre":"web","genre_label":"Web開発・言語","headline":"仕様書をコードに含め、コードを仕様の正（SSoT）にする手法","summary":"自然言語の仕様書とコードの乖離を防ぐため、可読性の高いコードを仕様の正（SSoT）とするアプローチを提案。仕様を厳密に書こうとするとコードに近づくため、最初から仕様書のように読めるコードを書くべきだと主張しています。\n\n人間がレビューすべきはドメイン層に絞り、それ以外はAIに任せるという役割分担を推奨。AIが生成する曖昧な文書ではなく、コンパイラやテストで正しさが担保されるコードを成果物とすることで、ソフトウェア開発の信頼性を高める設計思想を説いています。","importance":8},{"title":"Agent Harnessを理解するために、150行ほどのPythonで自作してみた - Qiita","url":"https://qiita.com/yamamoto_a_genee/items/76562c5c80032ad9e962","source":"Hatena","published_at":"2026-11-22 17:32","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI Agentの仕組みを理解する「Agent Harness」自作入門","summary":"AI Coding Agentの精度や使い勝手を左右する「Agent Harness（実行・制御の仕組み）」の概念を整理し、Pythonで150行の簡易実装を行う解説記事。LLM単体では不可能なファイル操作やプロセス実行を、Harnessがどのように制御しているかを実証する。\n\nツール呼び出し、ガードレール、可観測性といったHarnessの主要機能を実装することで、AIエージェントの内部構造を深く理解できる。信頼できないコードを実行する際の隔離の重要性についても触れられており、エージェント開発の基礎を学ぶのに適した内容である。","importance":7},{"title":"Next.jsのストリーミングはLambda Web Functionsで動くか","url":"https://zenn.dev/ryota_09/articles/nextjs-suspense-streaming-lambda-web-functions","source":"Zenn","published_at":"2026-11-22 11:30","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Next.jsのストリーミングはLambda Web Functionsで動作可能","summary":"Next.jsのSuspenseストリーミング機能が、AWS Lambdaの新しい実行形態「Lambda Web Functions」で正しく動作するかを実測検証したレポート。以前のLambda Web Adapterでは段階表示が困難でしたが、Web Functionsでは追加設定なしでVercelと同等のストリーミング挙動を確認しました。\n\n計測にはCloudFront経由のアクセスやコールドスタート時の挙動を含め、複数のアプリ構成で検証。結果として、Web FunctionsはNext.jsのSSRストリーミングを実用レベルでサポートしており、サーバーレス環境でのパフォーマンス向上に寄与することを示唆しています。","importance":8},{"title":"MCP EventsをMastraとMCPJam CLIで試してみる","url":"https://zenn.dev/cdata_japan/articles/1206f32306fd34","source":"Zenn","published_at":"2026-11-22 23:43","genre":"web","genre_label":"Web開発・言語","headline":"MCP Eventsの仕組みをMastraとMCPJam CLIで手元で試す実践編","summary":"MCP（Model Context Protocol）の公式拡張「MCP Events」の仕組みを、MastraとMCPJam CLIを用いて手元で検証する実践的な手順を紹介した記事です。list、push、poll、webhookの4つのイベント配信方式を実際に動かす方法を解説しています。\n\nstdio版とStreamable HTTP版の両方で動作を確認し、特定のイベントを絞り込むフィルタリング機能の実装方法も示されています。仕様を眺めるだけでなく、実際に手を動かしてイベントが届く手応えを確認するための具体的な環境構築と実行手順がまとめられています。","importance":5},{"title":"堅牢な受け入れテストを書くには？","url":"https://zenn.dev/yasuakiomokawa/articles/3ac970c3a3a1c7","source":"Zenn","published_at":"2026-11-21 18:09","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIコーディングエージェントに堅牢なテストを書かせる4手順","summary":"AIエージェントが生成するテストコードが実装変更ですぐ壊れる問題に対し、堅牢なテストを書かせるための4つの手順を提案。実装の詳細に依存せず、外から見える振る舞いのみを基準に書かせることの重要性を説いています。\n\n具体的な手法として、型検査やlintの活用、既存テストへの倣い、テストの実行確認を推奨。テストを「凍結」して書き換えを禁止するのではなく、基準の書き方を見直すことで、AIとの協働におけるテストの信頼性を高める方法を解説しています。","importance":8},{"title":"ここまで情報漏洩してもGoogle、Amazon、Apple辺りがやらかしていないのは流石では？→漏洩させている側がサイバー攻撃用にクラウドを使っているからできない説が浮上","url":"https://togetter.com/li/2773653","source":"Hatena","published_at":"2026-11-22 16:09","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"GAFAがサイバー攻撃の足場として悪用される現状と考察","summary":"Google Cloudなどの大手クラウドサービスが、サイバー攻撃者のインフラとして悪用されている現状についての議論。攻撃者がクラウドを足場にスキャン攻撃を行うため、クラウド事業者が自社サービスを攻撃できないというパラドックスが指摘されている。\n\n日本企業におけるセキュリティ意識の低さと比較し、GAFAの堅牢性が話題に上る一方、クラウドが攻撃の温床となっている実態は無視できない。セキュリティ対策の難しさと、プラットフォーム側の責任範囲について考えさせられる内容である。","importance":6},{"title":"Astro で作った健康情報サイトの SEO 対策 ― 何のために、Google は何を見ているのか（個人開発）","url":"https://zenn.dev/primal_scream/articles/f7e41f776e13ab","source":"Zenn","published_at":"2026-11-22 12:50","genre":"web","genre_label":"Web開発・言語","headline":"Astro製サイトにおけるSEOの基本とGoogle検索の仕組み","summary":"個人開発の健康情報サイトを運営する著者が、Astroを用いたフロントエンド実装におけるSEO対策を解説。Google検索の仕組みを「クロール」「インデックス」「検索結果表示」の3段階で捉え、それぞれの段階でGoogleが迷わないための正規化（URLの統一）や、適切なタイトル・見出し設定の重要性を説いています。\n\n具体的には、末尾スラッシュの有無や旧ドメインからのリダイレクト設定、canonicalタグの適切な運用など、技術的な実装手法を詳述。SEO対策は単なる順位向上策ではなく、検索エンジンに正しくサイトを認識させるための基盤整備であると結論づけています。","importance":6},{"title":"【TLA+】AIにテストケースを書かせるな。ルールを書け","url":"https://zenn.dev/karamage/articles/73027ee36796dc","source":"Zenn","published_at":"2026-11-21 11:12","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代におけるテストのあり方：ケースではなくルールを書く","summary":"AIが実装とテストの両方を書くことで生じる「自作自演の満点」という問題を指摘し、テストケースの記述から「守るべきルール」の記述への転換を提唱。TLA+やQuintを用いたモデル検査の考え方を応用し、システムが破綻してはならない制約を定義する手法を解説しています。\n\n人間は採点基準（ルール）を決め、問題生成は機械に任せるという役割分担を提案。AIの生成物に依存せず、数学的・論理的な裏付けを持ってシステムの安全性を担保する次世代のテスト戦略を提示しています。","importance":9},{"title":"ゲーム理論×シミュレーション: 囚人のジレンマにおける戦略と Rust による実装","url":"https://zenn.dev/akitenkrad/articles/1zqjjioamhlyg2","source":"Zenn","published_at":"2026-11-23 08:00","genre":"web","genre_label":"Web開発・言語","headline":"繰り返し囚人のジレンマにおける戦略分析とRustによる総当たりシミュレーション","summary":"ゲーム理論における「繰り返し囚人のジレンマ」を題材に、18種類の戦略をRustで実装し、総当たりトーナメントによるシミュレーション結果を分析した記事です。平均利得と勝敗という異なる指標を用いて、どの戦略が優位かを検証しています。\n\n記事では、決定論的および確率的な戦略を実装し、平均利得に基づいた順位付けを行いました。個々の対戦における勝敗と、トーナメント全体での利得最大化が必ずしも一致しないというゲーム理論の特性を、Rustによる実装を通じて解説しています。","importance":4}]};
